// ── Reproduce: minimal failing case ─────────────────────────────
// Bug reported: 'totals are sometimes wrong in the cart'
// DON'T dive into 800-line Cart component first.
// DO isolate the calculation function and test it directly:
function calcCartTotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}
// Reproduce with minimal input:
console.log(calcCartTotal([{ price: 9.99, qty: 2 }])); // expected 19.98
console.log(calcCartTotal([{ price: 9.99, qty: '2' }])); // bug! '2' is a string → NaN or '19.9819.98'
// Root cause: qty comes as a string from the API — coerce it
function calcCartTotalFixed(items) {
  return items.reduce((sum, item) => sum + item.price * Number(item.qty), 0);
}
console.log(calcCartTotalFixed([{ price: 9.99, qty: '2' }])); // 19.98

// ── Assertion-driven debugging ────────────────────────────────────
function divide(a, b) {
  console.assert(b !== 0, `divide called with b=0, a=${a}`); // fires if assumption violated
  return a / b;
}
divide(10, 0); // Assertion failed: divide called with b=0, a=10

// ── Structured logging with levels ───────────────────────────────
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';
const LEVELS = { debug: 0, info: 1, warn: 2, error: 3 };
function log(level, msg, data = {}) {
  if (LEVELS[level] >= LEVELS[LOG_LEVEL]) {
    console[level](`[${level.toUpperCase()}] ${msg}`, data);
  }
}
function processPayment(order) {
  log('debug', 'processPayment enter', { orderId: order.id, amount: order.total });
  // ... processing ...
  log('info',  'processPayment success', { orderId: order.id });
}
processPayment({ id: 42, total: 99.99 });
// With LOG_LEVEL=debug, both lines print; with LOG_LEVEL=info, only the success line prints

