// ── Defensive guard clauses surface assumptions ──────────────────
function getUsername(user) {
  if (!user)          throw new TypeError('getUsername: user is required');
  if (!user.name)     throw new TypeError('getUsername: user.name is missing');
  return user.name.trim();
}
// Without guards, a null user causes 'Cannot read property name of null'
// With guards, the error message points directly at the violated assumption
try { getUsername(null); } catch (e) { console.log(e.message); }
// getUsername: user is required

